import{_ as d,C as c,o as a,c as u,a0 as i,b as r,w as t,a as o,E as s,a1 as l}from"./chunks/framework.DYS8d9tm.js";const b=JSON.parse('{"title":"💳 Financial Instruments & Transfer Engine Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/financial_instruments.md","filePath":"technical/architecture/financial_instruments.md"}'),g={name:"technical/architecture/financial_instruments.md"};function m(p,e,h,f,v,y){const n=c("Mermaid");return a(),u("div",null,[e[2]||(e[2]=i('<h1 id="💳-financial-instruments-transfer-engine-architecture" tabindex="-1">💳 Financial Instruments &amp; Transfer Engine Architecture <a class="header-anchor" href="#💳-financial-instruments-transfer-engine-architecture" aria-label="Permalink to &quot;💳 Financial Instruments &amp; Transfer Engine Architecture&quot;">​</a></h1><p>This document outlines the architecture, data models, services, and UX parity for specialized financial instruments and cross-account transfer pairing in WealthFam.</p><hr><h2 id="_1-domain-separation-overview" tabindex="-1">1. Domain Separation Overview <a class="header-anchor" href="#_1-domain-separation-overview" aria-label="Permalink to &quot;1. Domain Separation Overview&quot;">​</a></h2><p>Prior to this architecture, credit cards, fixed deposits, and provident funds were treated as generic rows in the <code>accounts</code> table with generic metadata.</p><p>WealthFam implements a <strong>Domain-Separated Instrument Architecture</strong> where:</p><ol><li><code>accounts</code> acts as the universal double-entry ledger root (maintaining running balance, tenant isolation, and ownership).</li><li>Domain extension tables hold specialized instrument metadata and metrics (compounding frequencies, tripartite EPF shares, cycle dates, utilization).</li><li>Specialized services (<code>CreditCardService</code>, <code>FixedDepositService</code>, <code>ProvidentFundService</code>) own instrument lifecycle, analytics, and business rules.</li><li><code>AccountService</code> remains 100% instrument-agnostic.</li></ol>',7)),(a(),r(l,null,{default:t(()=>[s(n,{id:"mermaid-38",class:"mermaid",graph:"erDiagram%0A%20%20%20%20Account%20%7C%7C--o%7C%20CreditCardDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7C%20FixedDepositDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7C%20ProvidentFundDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7B%20Transaction%20%3A%20%221%3AN%20ledger%20entries%22%0A%20%20%20%20Transaction%20%7C%7C--o%7C%20Transaction%20%3A%20%22linked_transaction_id%20(Transfer%20Pair)%22%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<hr><h2 id="_2-supported-instrument-domains" tabindex="-1">2. Supported Instrument Domains <a class="header-anchor" href="#_2-supported-instrument-domains" aria-label="Permalink to &quot;2. Supported Instrument Domains&quot;">​</a></h2><h3 id="a-credit-cards" tabindex="-1">A. Credit Cards <a class="header-anchor" href="#a-credit-cards" aria-label="Permalink to &quot;A. Credit Cards&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>credit_card_details</code></li><li><strong>Model</strong>: <code>CreditCardDetails</code> (<code>account_id</code>, <code>credit_limit</code>, <code>billing_day</code>, <code>due_day</code>, <code>card_network</code>, <code>card_tier</code>, <code>card_last_4</code>, <code>apr_rate</code>, <code>autopay_enabled</code>)</li><li><strong>Key Concepts</strong>: <ul><li><strong>Single Source of Truth</strong>: User-configured <code>billing_day</code> (1–31) and <code>due_day</code> (1–31) are strictly preserved.</li><li><strong>Dynamic Billing Cycles</strong>: <code>CreditCardService.get_cycle_transactions()</code> supports segmenting transactions into <code>current_unbilled</code>, <code>last_statement</code>, and <code>all</code>.</li><li><strong>Bill Payment</strong>: Dedicated endpoint records double-entry transfers from bank accounts to credit card liabilities.</li></ul></li></ul><h3 id="b-fixed-recurring-deposits-fd-rd" tabindex="-1">B. Fixed &amp; Recurring Deposits (FD / RD) <a class="header-anchor" href="#b-fixed-recurring-deposits-fd-rd" aria-label="Permalink to &quot;B. Fixed &amp; Recurring Deposits (FD / RD)&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>fixed_deposit_details</code></li><li><strong>Model</strong>: <code>FixedDepositDetails</code> (<code>deposit_type</code>, <code>principal_amount</code>, <code>interest_rate</code>, <code>compounding_frequency</code>, <code>start_date</code>, <code>maturity_date</code>, <code>maturity_amount</code>, <code>monthly_deposit</code>)</li><li><strong>Key Concepts</strong>: <ul><li>Compounding frequency math (Monthly, Quarterly, Semi-Annual, Annual).</li><li>Accrued interest simulation up to the current wall-clock date.</li><li>Dynamic progress indicator percentage and days to maturity.</li></ul></li></ul><h3 id="c-provident-funds-epf-ppf-nps" tabindex="-1">C. Provident Funds (EPF / PPF / NPS) <a class="header-anchor" href="#c-provident-funds-epf-ppf-nps" aria-label="Permalink to &quot;C. Provident Funds (EPF / PPF / NPS)&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>provident_fund_details</code></li><li><strong>Model</strong>: <code>ProvidentFundDetails</code> (<code>fund_type</code>, <code>uan_number</code>, <code>pran_number</code>, <code>employee_share</code>, <code>employer_share</code>, <code>pension_share</code>, <code>annual_interest_rate</code>, <code>fy_contributions</code>)</li><li><strong>Key Concepts</strong>: <ul><li>Tripartite balance breakdown for EPF (Employee share, Employer share, EPS Pension share).</li><li>Annual interest estimation based on official statutory rates (e.g. 8.25% EPF, 7.10% PPF).</li><li>Post-tax statutory FY deposit tracking against the ₹1.5L statutory ceiling (PPF / EPF voluntary contributions).</li></ul></li></ul><h3 id="d-loans-liabilities" tabindex="-1">D. Loans &amp; Liabilities <a class="header-anchor" href="#d-loans-liabilities" aria-label="Permalink to &quot;D. Loans &amp; Liabilities&quot;">​</a></h3><ul><li>Enhanced with <code>lender_name</code> and <code>loan_account_number</code> for automated EMI detection and bank transfer linking.</li></ul><hr><h2 id="_3-intelligent-cross-account-transfer-engine" tabindex="-1">3. Intelligent Cross-Account Transfer Engine <a class="header-anchor" href="#_3-intelligent-cross-account-transfer-engine" aria-label="Permalink to &quot;3. Intelligent Cross-Account Transfer Engine&quot;">​</a></h2><p>Transfers between internal family accounts (e.g., Bank → Credit Card bill payment, Bank → Wife&#39;s Bank, Bank → Loan EMI) frequently enter the ledger as two disconnected transactions.</p><h3 id="heuristic-discovery-scoring" tabindex="-1">Heuristic Discovery &amp; Scoring <a class="header-anchor" href="#heuristic-discovery-scoring" aria-label="Permalink to &quot;Heuristic Discovery &amp; Scoring&quot;">​</a></h3><p><code>TransferDetectionService.scan_candidates()</code> inspects unlinked outflows (<code>amount &lt; 0</code>) and inflows (<code>amount &gt; 0</code>) within a configurable lookback window (default 90 days):</p><ul><li><strong>Asymmetric Matching</strong>: <ul><li>Exact match ($\\Delta &lt; ₹0.05$): High base confidence (75%).</li><li>Offer / Discount / Fee tolerance ($\\Delta \\le ₹500$ or ratio $\\ge 0.90$): Flagged with descriptive reason.</li><li>Part-payments: When recipient narrative explicitly cites destination card mask.</li></ul></li><li><strong>Date Proximity</strong>: Same day (+15%), 1 day apart (+10%), within 4 days (+5%).</li><li><strong>Identity &amp; Text Correlation</strong>: Account name mentions, card mask matches ($*1234$), and family member names.</li></ul><h3 id="human-in-the-loop-approval-parity" tabindex="-1">Human-in-the-Loop Approval &amp; Parity <a class="header-anchor" href="#human-in-the-loop-approval-parity" aria-label="Permalink to &quot;Human-in-the-Loop Approval &amp; Parity&quot;">​</a></h3><ul><li><strong>Zero Silent Merges</strong>: In accordance with enterprise audit standards, transfer matches are returned as suggestions for human review.</li><li><strong>Atomic Linking</strong>: When approved (<code>pair_transactions</code>), <code>linked_transaction_id</code> is mutually populated, and <code>exclude_from_reports = True</code> is assigned to both legs to prevent artificial inflation of income or expense totals while preserving double-entry ledger balance.</li><li><strong>Credit Card Dues Sync</strong>: Linking a transfer to a Credit Card automatically deducts the paid amount from <code>total_amount_due</code> and updates <code>min_amount_due</code>. Unlinking safely restores card dues.</li><li><strong>1-Click Counterpart Leg Generation</strong>: When an outflow is recognized as an internal transfer but the destination credit transaction is missing from statements, users can auto-generate the matching credit leg on the target account directly from either Web (<code>Transfers.vue</code>) or Mobile (<code>transfers_hub_screen.dart</code>), with adjustable credited amount for merchant discounts.</li><li><strong>Batch Approvals</strong>: Both Web and Mobile feature 1-click batch approval for high-confidence matches ($\\ge 80%$).</li></ul><hr><h2 id="_4-mobile-web-implementation-parity" tabindex="-1">4. Mobile &amp; Web Implementation Parity <a class="header-anchor" href="#_4-mobile-web-implementation-parity" aria-label="Permalink to &quot;4. Mobile &amp; Web Implementation Parity&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Instrument / Feature</th><th style="text-align:left;">Web Implementation</th><th style="text-align:left;">Mobile Implementation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Credit Cards</strong></td><td style="text-align:left;"><code>CreditCards.vue</code> &amp; Cycle Filtering</td><td style="text-align:left;">Direct drawer destination (<code>app_shell.dart</code>) &amp; <code>accounts_screen.dart</code></td></tr><tr><td style="text-align:left;"><strong>Deposits (FD / RD)</strong></td><td style="text-align:left;"><code>Deposits.vue</code> with Compounding Math</td><td style="text-align:left;"><code>deposits_screen.dart</code> with KPI strip &amp; maturity telemetry</td></tr><tr><td style="text-align:left;"><strong>Provident Funds</strong></td><td style="text-align:left;"><code>ProvidentFunds.vue</code> with Tripartite EPF</td><td style="text-align:left;"><code>provident_funds_screen.dart</code> &amp; <code>account_detail_screen.dart</code></td></tr><tr><td style="text-align:left;"><strong>Transfers Hub</strong></td><td style="text-align:left;"><code>Transfers.vue</code> (Detected, Unpaired, History)</td><td style="text-align:left;"><code>transfers_hub_screen.dart</code> with Batch Approve &amp; Counterpart Sheet</td></tr><tr><td style="text-align:left;"><strong>Transfer Unlinking</strong></td><td style="text-align:left;">1-Click Unlink with Ledger Rollback</td><td style="text-align:left;">Trailing <code>link_off</code> button with immediate balance refresh</td></tr><tr><td style="text-align:left;"><strong>MF Tax Optimization</strong></td><td style="text-align:left;"><code>TaxOptimizationCard.vue</code> (FIFO lots, Headroom gauge)</td><td style="text-align:left;"><code>mutual_funds_screen.dart</code> (Tax sub-view &amp; harvesting)</td></tr><tr><td style="text-align:left;"><strong>MF Portfolio Overlap</strong></td><td style="text-align:left;"><code>PortfolioOverlapCard.vue</code> (Pairwise matrix, Concentration)</td><td style="text-align:left;"><code>mutual_funds_screen.dart</code> (Overlap sub-view &amp; top stocks)</td></tr><tr><td style="text-align:left;"><strong>MF Sector Heatmap</strong></td><td style="text-align:left;"><code>SectorHeatmapCard.vue</code> (12 sectors, Pareto drilldown)</td><td style="text-align:left;"><code>mutual_funds_screen.dart</code> (Sector sub-view &amp; cap bars)</td></tr><tr><td style="text-align:left;"><strong>MF SIP Intelligence</strong></td><td style="text-align:left;"><code>SipIntelligenceCard.vue</code> (Calendar, Step-Up simulator)</td><td style="text-align:left;"><code>mutual_funds_screen.dart</code> (SIP sub-view &amp; Liquidity match)</td></tr><tr><td style="text-align:left;"><strong>MF Peer Benchmarking</strong></td><td style="text-align:left;"><code>PeerComparisonCard.vue</code> (SVG Quadrant, Glassmorphic AI)</td><td style="text-align:left;"><code>mutual_funds_screen.dart</code> (CustomPaint Canvas Quadrant)</td></tr></tbody></table><hr><h2 id="_5-mutual-fund-intelligence-analytical-engine-architecture" tabindex="-1">5. Mutual Fund Intelligence &amp; Analytical Engine Architecture <a class="header-anchor" href="#_5-mutual-fund-intelligence-analytical-engine-architecture" aria-label="Permalink to &quot;5. Mutual Fund Intelligence &amp; Analytical Engine Architecture&quot;">​</a></h2><p>The Mutual Fund Intelligence Suite provides deep portfolio diagnostics, tax harvesting, risk-return profiling, and cash-flow matching across five dedicated service domains:</p>',24)),(a(),r(l,null,{default:t(()=>[s(n,{id:"mermaid-379",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Holdings%5B(mutual_fund_holdings)%5D%20--%3E%20TaxSvc%5BMFTaxService%5D%0A%20%20%20%20Orders%5B(mutual_fund_orders)%5D%20--%3E%20TaxSvc%0A%20%20%20%20Holdings%20--%3E%20OverlapSvc%5BMFPortfolioOverlapService%5D%0A%20%20%20%20Constituents%5B(mutual_fund_constituents)%5D%20--%3E%20OverlapSvc%0A%20%20%20%20Holdings%20--%3E%20SectorSvc%5BMFSectoralService%5D%0A%20%20%20%20Constituents%20--%3E%20SectorSvc%0A%20%20%20%20Orders%20--%3E%20SipSvc%5BMFSipService%5D%0A%20%20%20%20Sips%5B(mutual_fund_sips)%5D%20--%3E%20SipSvc%0A%20%20%20%20BankLedger%5B(accounts%20%2F%20balances)%5D%20--%3E%20SipSvc%0A%20%20%20%20Holdings%20--%3E%20PeerSvc%5BMFPeerAnalyticsService%5D%0A%20%20%20%20Benchmarks%5B(mutual_fund_benchmarks)%5D%20--%3E%20PeerSvc%0A%0A%20%20%20%20TaxSvc%20--%3E%20API%5B%22%2Fapi%2Fv1%2Ffinance%2Fmutual-funds%2Fintelligence%2F*%22%5D%0A%20%20%20%20OverlapSvc%20--%3E%20API%0A%20%20%20%20SectorSvc%20--%3E%20API%0A%20%20%20%20SipSvc%20--%3E%20API%0A%20%20%20%20PeerSvc%20--%3E%20API%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h3 id="a-fifo-tax-optimization-harvesting-engine-mftaxservice" tabindex="-1">A. FIFO Tax Optimization &amp; Harvesting Engine (<code>MFTaxService</code>) <a class="header-anchor" href="#a-fifo-tax-optimization-harvesting-engine-mftaxservice" aria-label="Permalink to &quot;A. FIFO Tax Optimization &amp; Harvesting Engine (`MFTaxService`)&quot;">​</a></h3><ul><li><strong>Engine Logic</strong>: Performs FIFO lot-by-lot decomposition by matching historical <code>BUY</code> orders against active holding units.</li><li><strong>Indian Finance Act 2024 Compliance</strong>: Applies 12.5% tax for LTCG (equity $&gt; 365$ days) above the ₹1.25L annual exemption threshold, and 20% for STCG ($\\le 365$ days). For debt funds (equity $&lt; 35%$), gains are classified as slab-rate income.</li><li><strong>Opportunity Detection</strong>: Surfaces lots for tax-loss harvesting and flags near-LTCG lots (315 to 365 days) to protect users against accidental premature sales.</li></ul><h3 id="b-portfolio-overlap-concentration-engine-mfportfoliooverlapservice" tabindex="-1">B. Portfolio Overlap &amp; Concentration Engine (<code>MFPortfolioOverlapService</code>) <a class="header-anchor" href="#b-portfolio-overlap-concentration-engine-mfportfoliooverlapservice" aria-label="Permalink to &quot;B. Portfolio Overlap &amp; Concentration Engine (`MFPortfolioOverlapService`)&quot;">​</a></h3><ul><li><strong>Pairwise Matrix</strong>: Computes common stock weights across active holdings: $\\text{Overlap}(A, B) = \\sum_{i} \\min(w_{A, i}, w_{B, i})$.</li><li><strong>Aggregate Stock Concentration</strong>: Deconstructs fund holdings into underlying corporate entities using curated profiles in <code>mutual_fund_constituents</code> and archetype fallback models.</li><li><strong>Severity Scoring</strong>: Alerts on single-company concentration exceeding 10% (Warning) or 15% (Critical) and calculates a 0–100 Portfolio Diversity Index.</li></ul><h3 id="c-sectoral-heatmap-market-cap-aggregator-mfsectoralservice" tabindex="-1">C. Sectoral Heatmap &amp; Market Cap Aggregator (<code>MFSectoralService</code>) <a class="header-anchor" href="#c-sectoral-heatmap-market-cap-aggregator-mfsectoralservice" aria-label="Permalink to &quot;C. Sectoral Heatmap &amp; Market Cap Aggregator (`MFSectoralService`)&quot;">​</a></h3><ul><li><strong>12 Standard Sectors</strong>: Aggregates equity weights across 12 standard sectors (Financials, Technology, Healthcare, Energy, Automobile, Consumer, etc.).</li><li><strong>Cap Breakdown</strong>: Categorizes portfolio into Large Cap, Mid Cap, Small Cap, and Cash &amp; Debt components.</li><li><strong>Constituent Drilldown</strong>: Returns top contributing stocks per sector with company names and effective portfolio weights.</li></ul><h3 id="d-sip-intelligence-cash-flow-matching-mfsipservice" tabindex="-1">D. SIP Intelligence &amp; Cash-Flow Matching (<code>MFSipService</code>) <a class="header-anchor" href="#d-sip-intelligence-cash-flow-matching-mfsipservice" aria-label="Permalink to &quot;D. SIP Intelligence &amp; Cash-Flow Matching (`MFSipService`)&quot;">​</a></h3><ul><li><strong>Automated Detection</strong>: Analyzes transaction timestamps, recurring order values, and descriptions to infer active monthly SIPs and execution days, persisting records in <code>mutual_fund_sips</code>.</li><li><strong>Verified vs Inferred Status</strong>: Supports 1-tap confirmation toggle (<code>is_auto_detected = False</code>) and active status management (<code>ACTIVE</code>, <code>PAUSED</code>).</li><li><strong>Liquidity Buffer Matching</strong>: Integrates primary liquid bank balances (<code>AccountType.BANK</code>) to forecast 30-day debit commitments and detect liquidity shortfalls before auto-debits trigger penalty charges.</li><li><strong>Step-Up Projections</strong>: 10-year compounding wealth models across 0%, 5%, 10%, and 15% annual step-up rates.</li></ul><h3 id="e-quantitative-peer-benchmarking-risk-return-quadrant-mfpeeranalyticsservice" tabindex="-1">E. Quantitative Peer Benchmarking &amp; Risk-Return Quadrant (<code>MFPeerAnalyticsService</code>) <a class="header-anchor" href="#e-quantitative-peer-benchmarking-risk-return-quadrant-mfpeeranalyticsservice" aria-label="Permalink to &quot;E. Quantitative Peer Benchmarking &amp; Risk-Return Quadrant (`MFPeerAnalyticsService`)&quot;">​</a></h3><ul><li><strong>Quantitative Metrics</strong>: Computes Jensen&#39;s Alpha ($\\alpha$), Beta ($\\beta$), Sharpe ratio, and annualized volatility against AMFI category Total Return Indices (TRI).</li><li><strong>Coordinate Mapping &amp; Parity</strong>: <ul><li>$X$-axis: Portfolio Beta clamped to $[0.5, 1.5]$ with center market reference $\\beta = 1.0$.</li><li>$Y$-axis: Jensen&#39;s Alpha clamped to $[-8.0%, +12.0%]$ with zero-excess return axis $\\alpha = 0.0%$.</li><li>Visualized via interactive SVG on Web with radial gradient quadrant zones, glowing double-ring portfolio target, and glassmorphic tooltips; implemented via native <code>CustomPaint</code> canvas in Flutter on Mobile.</li></ul></li><li><strong>Posture Evaluation</strong>: Automatically evaluates capital efficiency into 4 distinct quadrants: ⭐ <em>Star Outperformer</em>, 🚀 <em>Aggressive Alpha</em>, 🛡️ <em>Defensive Value</em>, and ⚠️ <em>High Risk Lagging</em>.</li><li><strong>Section 16.1 AI Advisor Report</strong>: Comprehensive advisory summary adhering strictly to enterprise financial reporting standards.</li></ul><h3 id="f-multi-tenant-family-member-scoping" tabindex="-1">F. Multi-Tenant &amp; Family Member Scoping <a class="header-anchor" href="#f-multi-tenant-family-member-scoping" aria-label="Permalink to &quot;F. Multi-Tenant &amp; Family Member Scoping&quot;">​</a></h3><ul><li>All endpoints accept an optional <code>user_id</code> query parameter.</li><li>When <code>user_id</code> is passed, holdings, orders, and SIPs are scoped to <code>MutualFundHolding.user_id == user_id</code>.</li><li>When <code>user_id</code> is null or omitted, data aggregates across all authorized tenant members for consolidated household intelligence.</li><li>Role-Based Access Control (RBAC) automatically restricts users with the <code>CHILD</code> role to their own user ID.</li></ul>',12))])}const S=d(g,[["render",m]]);export{b as __pageData,S as default};
